(615, '3.2.398', 46, 'Einfacher Graph', 'Graph ohne Mehrfachkanten und Schleifen.', '\\{v_i,v_i\\}\\notin E', '\\{v_i,v_i\\}\\notin E', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(616, '3.2.399', 46, 'Gewichteter Graph', 'Graph mit einer Gewichtsfunktion auf der Kantenmenge.', 'w:E\\rightarrow\\mathbb{R}', 'w:E\\rightarrow\\mathbb{R}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(617, '3.2.400', 46, 'Nachbarschaft eines Knotens', 'Menge aller unmittelbar mit einem Knoten verbundenen Knoten.', 'N(v_i)=\\{v_j\\in V\\mid\\{v_i,v_j\\}\\in E\\}', 'N(v_i)=\\{v_j\\in V\\mid\\{v_i,v_j\\}\\in E\\}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(618, '3.2.401', 46, 'Eingangs- und Ausgangsnachbarschaft', 'Nachbarschaften eines gerichteten Graphen getrennt nach Kantenrichtung.', 'N^{+}(v_i),\\ N^{-}(v_i)', 'N^{+}(v_i),\\ N^{-}(v_i)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(619, '3.2.402', 46, 'Grad eines Knotens', 'Anzahl der Nachbarn eines Knotens in einem ungerichteten Graphen.', 'd_i=\\deg(v_i)=|N(v_i)|', 'd_i=\\deg(v_i)=|N(v_i)|', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(620, '3.2.403', 46, 'Eingangs- und Ausgangsgrad', 'Anzahl eingehender beziehungsweise ausgehender Kanten eines Knotens.', 'd_i^{+}=|N^{+}(v_i)|,\\quad d_i^{-}=|N^{-}(v_i)|', 'd_i^{+}=|N^{+}(v_i)|,\\quad d_i^{-}=|N^{-}(v_i)|', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(621, '3.2.404', 46, 'Gewichteter Knotengrad', 'Summe der an einem Knoten anliegenden Kantengewichte.', 's_i=\\sum_{j=1}^{n}w_{ij}', 's_i=\\sum_{j=1}^{n}w_{ij}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(622, '3.2.405', 46, 'Adjazenzmatrix', 'Matrixdarstellung der Kantenbeziehungen eines Graphen.', 'A=(a_{ij})_{i,j=1}^{n}', 'A=(a_{ij})_{i,j=1}^{n}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49);
INSERT INTO `definitions` (`definition_id`, `definition_number`, `section_id`, `title`, `definition_text`, `formal_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `notes`, `validation_status`, `created_revision_id`) VALUES
(623, '3.2.406', 46, 'Gradmatrix', 'Diagonalmatrix der Knotengrade eines Graphen.', 'D=\\operatorname{diag}(d_1,\\ldots,d_n)', 'D=\\operatorname{diag}(d_1,\\ldots,d_n)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(624, '3.2.407', 46, 'Weg', 'Folge von Knoten, bei der aufeinanderfolgende Knoten durch Kanten verbunden sind.', 'v_{i_0},v_{i_1},\\ldots,v_{i_k}', 'v_{i_0},v_{i_1},\\ldots,v_{i_k}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(625, '3.2.408', 46, 'Pfad', 'Weg ohne mehrfach vorkommende Knoten.', '\\ell(P)=k', '\\ell(P)=k', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(626, '3.2.409', 46, 'Zyklus', 'Geschlossener Weg mit identischem Anfangs- und Endknoten.', 'v_{i_0}=v_{i_k}', 'v_{i_0}=v_{i_k}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(627, '3.2.410', 46, 'Zusammenhängender Graph', 'Graph, in dem jedes Knotenpaar durch einen Pfad verbunden ist.', '\\forall v_i,v_j\\in V\\ \\exists\\text{ Pfad }v_i\\leadsto v_j', '\\forall v_i,v_j\\in V\\ \\exists\\text{ Pfad }v_i\\leadsto v_j', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(628, '3.2.411', 46, 'Zusammenhangskomponente', 'Maximal zusammenhängender Teilgraph.', 'c(G)', 'c(G)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(629, '3.2.412', 46, 'Graphendistanz', 'Länge eines kürzesten Pfades zwischen zwei Knoten.', 'd_G(v_i,v_j)=\\min\\{\\ell(P)\\mid P:v_i\\leadsto v_j\\}', 'd_G(v_i,v_j)=\\min\\{\\ell(P)\\mid P:v_i\\leadsto v_j\\}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(630, '3.2.413', 46, 'Exzentrizität', 'Größte Distanz eines Knotens zu einem anderen Knoten.', '\\varepsilon(v_i)=\\max_{v_j\\in V}d_G(v_i,v_j)', '\\varepsilon(v_i)=\\max_{v_j\\in V}d_G(v_i,v_j)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(631, '3.2.414', 46, 'Radius und Durchmesser', 'Minimum beziehungsweise Maximum der Knotenexzentrizitäten.', 'r(G)=\\min_i\\varepsilon(v_i),\\quad\\operatorname{diam}(G)=\\max_i\\varepsilon(v_i)', 'r(G)=\\min_i\\varepsilon(v_i),\\quad\\operatorname{diam}(G)=\\max_i\\varepsilon(v_i)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(632, '3.2.415', 46, 'Kombinatorische Laplace-Matrix', 'Differenz aus Gradmatrix und Adjazenzmatrix.', 'L=D-A', 'L=D-A', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(633, '3.2.416', 46, 'Wirkung des Graph-Laplace-Operators', 'Vergleich eines Knotenwertes mit den Werten seiner Nachbarn.', '(Lx)_i=\\sum_{j=1}^{n}a_{ij}(x_i-x_j)', '(Lx)_i=\\sum_{j=1}^{n}a_{ij}(x_i-x_j)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(634, '3.2.417', 46, 'Algebraische Zusammenhangszahl', 'Zweitkleinster Eigenwert der Laplace-Matrix.', '\\lambda_2(L)', '\\lambda_2(L)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(635, '3.2.418', 46, 'Symmetrisch normierte Laplace-Matrix', 'Symmetrisch gradnormierte Form der Laplace-Matrix.', 'L_{\\mathrm{sym}}=I-D^{-1/2}AD^{-1/2}', 'L_{\\mathrm{sym}}=I-D^{-1/2}AD^{-1/2}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(636, '3.2.419', 46, 'Zufallsweg-Laplace-Matrix', 'Normierte Laplace-Matrix in Beziehung zur Übergangsmatrix eines Zufallswegs.', 'L_{\\mathrm{rw}}=I-D^{-1}A', 'L_{\\mathrm{rw}}=I-D^{-1}A', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(637, '3.2.420', 46, 'Inzidenzmatrix', 'Matrix der Zuordnung orientierter Kanten zu ihren Endknoten.', 'B\\in\\mathbb{R}^{n\\times m}', 'B\\in\\mathbb{R}^{n\\times m}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(638, '3.2.421', 46, 'Diskreter Gradient', 'Kantendifferenzen eines Knotenwertvektors.', '\\nabla_Gx=B^{\\mathsf{T}}x', '\\nabla_Gx=B^{\\mathsf{T}}x', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(639, '3.2.422', 46, 'Diskrete Divergenz', 'Knotenbilanz eines Kantenflusses.', '\\operatorname{div}_Gf=Bf', '\\operatorname{div}_Gf=Bf', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(640, '3.2.423', 46, 'Dirichlet-Energie auf einem Graphen', 'Quadratisches Maß der Unterschiede benachbarter Knotenwerte.', '\\mathcal{E}_G(x)=x^{\\mathsf{T}}Lx', '\\mathcal{E}_G(x)=x^{\\mathsf{T}}Lx', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(641, '3.2.424', 46, 'Graph-Wärmekern', 'Matrixexponential der negativen Laplace-Matrix.', 'K_t=\\exp(-tL)', 'K_t=\\exp(-tL)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(642, '3.2.425', 46, 'Lineare Konsensdynamik', 'Dynamik zur Angleichung gekoppelter Knotenwerte.', '\\frac{\\mathrm{d}x}{\\mathrm{d}t}=-Lx', '\\frac{\\mathrm{d}x}{\\mathrm{d}t}=-Lx', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(643, '3.2.426', 46, 'Übergangsmatrix eines Zufallswegs', 'Gradnormierte Adjazenzmatrix eines einfachen Zufallswegs.', 'P=D^{-1}A', 'P=D^{-1}A', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(644, '3.2.427', 46, 'Stationäre Verteilung eines Zufallswegs', 'Verteilung, die unter Anwendung der Übergangsmatrix unverändert bleibt.', '\\pi^{\\mathsf{T}}P=\\pi^{\\mathsf{T}}', '\\pi^{\\mathsf{T}}P=\\pi^{\\mathsf{T}}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(645, '3.2.428', 46, 'Gradzentralität', 'Normierter Knotengrad als Zentralitätsmaß.', 'C_D(v_i)=\\frac{d_i}{n-1}', 'C_D(v_i)=\\frac{d_i}{n-1}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(646, '3.2.429', 46, 'Nähezentralität', 'Kehrwert der mittleren Distanz eines Knotens zu allen anderen Knoten.', 'C_C(v_i)=\\frac{n-1}{\\sum_{j\\neq i}d_G(v_i,v_j)}', 'C_C(v_i)=\\frac{n-1}{\\sum_{j\\neq i}d_G(v_i,v_j)}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(647, '3.2.430', 46, 'Zwischenzentralität', 'Anteil kürzester Pfade, die durch einen Knoten verlaufen.', 'C_B(v_i)=\\sum\\frac{\\sigma_{st}(v_i)}{\\sigma_{st}}', 'C_B(v_i)=\\sum\\frac{\\sigma_{st}(v_i)}{\\sigma_{st}}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(648, '3.2.431', 46, 'Eigenvektorzentralität', 'Zentralitätsmaß als Eigenvektor der Adjazenzmatrix.', 'Ac=\\lambda c', 'Ac=\\lambda c', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(649, '3.2.432', 46, 'Induzierter Teilgraph', 'Teilgraph auf einer Knotenmenge mit allen zwischen diesen Knoten vorhandenen Kanten.', 'G[S]=(S,E_S)', 'G[S]=(S,E_S)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(650, '3.2.433', 46, 'Schnittkante', 'Kante zwischen einer Knotenmenge und ihrem Komplement.', '\\partial S=\\{\\{v_i,v_j\\}\\in E\\mid v_i\\in S,\\ v_j\\notin S\\}', '\\partial S=\\{\\{v_i,v_j\\}\\in E\\mid v_i\\in S,\\ v_j\\notin S\\}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(651, '3.2.434', 46, 'Volumen einer Knotenmenge', 'Summe der Knotengrade innerhalb einer Knotenmenge.', '\\operatorname{vol}(S)=\\sum_{v_i\\in S}d_i', '\\operatorname{vol}(S)=\\sum_{v_i\\in S}d_i', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(652, '3.2.435', 46, 'Leitfähigkeit eines Schnitts', 'Normiertes Maß für die Randkopplung einer Knotenmenge.', '\\phi(S)=\\frac{|\\partial S|}{\\min(\\operatorname{vol}(S),\\operatorname{vol}(V\\setminus S))}', '\\phi(S)=\\frac{|\\partial S|}{\\min(\\operatorname{vol}(S),\\operatorname{vol}(V\\setminus S))}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(653, '3.2.436', 46, 'Zeitabhängiger Graph', 'Graphenfamilie mit zeitabhängigen Knoten, Kanten oder Gewichten.', 'G(t)=(V(t),E(t))', 'G(t)=(V(t),E(t))', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(654, '3.2.437', 46, 'Temporaler Pfad', 'Zeitlich zulässige Folge von Kanten mit nicht abnehmenden Zeitpunkten.', 't_1\\leq t_2\\leq\\cdots\\leq t_k', 't_1\\leq t_2\\leq\\cdots\\leq t_k', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(655, '3.2.438', 46, 'Mehrschichtiger Graph', 'Netzwerk aus mehreren Beziehungsebenen.', 'G^{(1)},G^{(2)},\\ldots,G^{(m)}', 'G^{(1)},G^{(2)},\\ldots,G^{(m)}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(656, '3.2.439', 46, 'Supra-Adjazenzmatrix', 'Blockmatrix für inner- und zwischenschichtige Kopplungen.', '\\mathcal{A}=\\begin{pmatrix}A^{(1)}&C^{(12)}\\\\C^{(21)}&A^{(2)}\\end{pmatrix}', '\\mathcal{A}=\\begin{pmatrix}A^{(1)}&C^{(12)}\\\\C^{(21)}&A^{(2)}\\end{pmatrix}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(657, '3.2.440', 46, 'FRZK-Kopplungsgraph', 'Gewichteter, gegebenenfalls gerichteter Graph funktionaler Zustandskomponenten.', 'G_{\\mathrm{FRZK}}=(V_{\\mathrm{F}},E_{\\mathrm{F}},w_{\\mathrm{F}})', 'G_{\\mathrm{FRZK}}=(V_{\\mathrm{F}},E_{\\mathrm{F}},w_{\\mathrm{F}})', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(658, '3.2.441', 46, 'FRZK-Adjazenzoperator', 'Matrix der direkten funktionalen Wirkungen zwischen FRZK-Zustandskomponenten.', 'A_{\\mathrm{F}}=(a_{ij}^{\\mathrm{F}})', 'A_{\\mathrm{F}}=(a_{ij}^{\\mathrm{F}})', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(659, '3.2.442', 46, 'FRZK-Kopplungsstärke', 'Summierte ein- beziehungsweise ausgehende Kopplungsgewichte einer Zustandskomponente.', 's_i^{\\mathrm{in}}=\\sum_j a_{ij}^{\\mathrm{F}}', 's_i^{\\mathrm{in}}=\\sum_j a_{ij}^{\\mathrm{F}}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(660, '3.2.443', 46, 'FRZK-Laplace-Operator', 'Laplace-Operator eines symmetrischen nichtnegativ gewichteten FRZK-Kopplungsgraphen.', 'L_{\\mathrm{F}}=D_{\\mathrm{F}}-A_{\\mathrm{F}}', 'L_{\\mathrm{F}}=D_{\\mathrm{F}}-A_{\\mathrm{F}}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(661, '3.2.444', 46, 'Funktionale Graph-Energie des FRZK', 'Quadratische Energie der Zustandsunterschiede entlang der FRZK-Kanten.', 'E_{\\mathrm{F}}(u)=u^{\\mathsf{T}}L_{\\mathrm{F}}u', 'E_{\\mathrm{F}}(u)=u^{\\mathsf{T}}L_{\\mathrm{F}}u', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(662, '3.2.445', 46, 'Graphbasierte FRZK-Kohärenz', 'Normierte Ergänzung der funktionalen Graph-Energie.', 'K_G(u)=\\frac{1}{1+E_{\\mathrm{F}}(u)}', 'K_G(u)=\\frac{1}{1+E_{\\mathrm{F}}(u)}', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(663, '3.2.446', 46, 'Zeitabhängiger FRZK-Kopplungsgraph', 'FRZK-Kopplungsgraph mit zeitabhängigen Kanten oder Gewichten.', 'G_{\\mathrm{F}}(t)=(V_{\\mathrm{F}},E_{\\mathrm{F}}(t),w_{\\mathrm{F}}(t))', 'G_{\\mathrm{F}}(t)=(V_{\\mathrm{F}},E_{\\mathrm{F}}(t),w_{\\mathrm{F}}(t))', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(664, '3.2.447', 46, 'FRZK-Kopplungsdrift', 'Änderung der FRZK-Adjazenzmatrix zwischen zwei Zeitpunkten.', '\\Delta A_{\\mathrm{F}}=A_{\\mathrm{F}}(t_2)-A_{\\mathrm{F}}(t_1)', '\\Delta A_{\\mathrm{F}}=A_{\\mathrm{F}}(t_2)-A_{\\mathrm{F}}(t_1)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(665, '3.2.448', 46, 'Gekoppelte Struktur-Zustands-Dynamik', 'Wechselseitige zeitliche Entwicklung von Zustandsvektor und Netzwerkstruktur.', '\\dot{u}=F(u,A,t),\\quad\\dot{A}=G(u,A,t)', '\\dot{u}=F(u,A,t),\\quad\\dot{A}=G(u,A,t)', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
(666, '3.2.449', 46, 'Graphbasierte FRZK-Beobachtbarkeit', 'Eindeutige Rekonstruierbarkeit eines graphbasierten Zustands aus Beobachtungen und bekanntem Kopplungsoperator.', '\\operatorname{rang}(\\mathcal{O})=n', '\\operatorname{rang}(\\mathcal{O})=n', 'adapted', 92, 'Voraussetzungen gemäß Abschnitt 3.2.29.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 49),
