(684, '3.2.459', 48, 'Gleichgewichtszustand eines kontinuierlichen Systems', 'Ein Zustand x* heißt Gleichgewichtszustand des autonomen Systems, wenn f(x*)=0 gilt.', 'f(x^\\ast)=0', 'f(x^\\ast)=0', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(685, '3.2.460', 48, 'Stationäre Lösung', 'Eine stationäre Lösung ist eine zeitlich konstante Lösung eines dynamischen Systems.', 'x(t)\\equiv x^\\ast', 'x(t)\\equiv x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(686, '3.2.461', 48, 'Fixpunkt eines diskreten Systems', 'Ein Zustand x* heißt Fixpunkt einer Abbildung F, wenn F(x*)=x* gilt.', 'F(x^\\ast)=x^\\ast', 'F(x^\\ast)=x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(687, '3.2.462', 48, 'Periodischer Punkt', 'Ein Zustand x* heißt periodischer Punkt der Periode p, wenn F^p(x*)=x* und für alle q<p keine frühere Rückkehr erfolgt.', 'F^p(x^\\ast)=x^\\ast', 'F^p(x^\\ast)=x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(688, '3.2.463', 48, 'Positiv invariante Menge', 'Eine Menge M heißt positiv invariant, wenn jede in M beginnende Trajektorie für alle zukünftigen Zeiten in M verbleibt.', 'x_0\\in M\\Longrightarrow\\Phi_t(x_0)\\in M\\quad\\forall t\\geq0', 'x_0\\in M\\Longrightarrow\\Phi_t(x_0)\\in M\\quad\\forall t\\geq0', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(689, '3.2.464', 48, 'Invariante Menge', 'Eine Menge M heißt invariant, wenn sie durch den Fluss auf sich selbst abgebildet wird.', '\\Phi_t(M)=M', '\\Phi_t(M)=M', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(690, '3.2.465', 48, 'Negativ invariante Menge', 'Eine Menge M heißt negativ invariant, wenn jede rückwärts fortsetzbare Trajektorie für negative Zeiten in M verbleibt.', 'x_0\\in M\\Longrightarrow\\Phi_t(x_0)\\in M\\quad\\forall t\\leq0', 'x_0\\in M\\Longrightarrow\\Phi_t(x_0)\\in M\\quad\\forall t\\leq0', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(691, '3.2.466', 48, 'Randinvarianz', 'Der Rand einer Menge heißt invariant, wenn er durch den Fluss nicht verlassen wird.', '\\Phi_t(\\partial M)\\subseteq\\partial M', '\\Phi_t(\\partial M)\\subseteq\\partial M', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(692, '3.2.467', 48, 'Umgebung eines Gleichgewichts', 'Die offene Epsilon-Umgebung eines Gleichgewichts besteht aus allen Zuständen mit Normabstand kleiner Epsilon.', 'B_\\varepsilon(x^\\ast)=\\{x\\in\\mathbb{R}^n\\mid\\|x-x^\\ast\\|<\\varepsilon\\}', 'B_\\varepsilon(x^\\ast)=\\{x\\in\\mathbb{R}^n\\mid\\|x-x^\\ast\\|<\\varepsilon\\}', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(693, '3.2.468', 48, 'Stabilität im Sinne von Lyapunov', 'Ein Gleichgewicht heißt stabil, wenn hinreichend kleine Anfangsstörungen für alle zukünftigen Zeiten klein bleiben.', '\\forall\\varepsilon>0\\ \\exists\\delta>0:\\|x_0-x^\\ast\\|<\\delta\\Rightarrow\\|x(t;x_0)-x^\\ast\\|<\\varepsilon', '\\forall\\varepsilon>0\\ \\exists\\delta>0:\\|x_0-x^\\ast\\|<\\delta\\Rightarrow\\|x(t;x_0)-x^\\ast\\|<\\varepsilon', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(694, '3.2.469', 48, 'Instabilität', 'Ein Gleichgewicht heißt instabil, wenn es nicht stabil im Sinne von Lyapunov ist.', '\\exists\\varepsilon_0>0\\ \\forall\\delta>0\\ \\exists x_0,t:\\|x_0-x^\\ast\\|<\\delta\\land\\|x(t;x_0)-x^\\ast\\|\\geq\\varepsilon_0', '\\exists\\varepsilon_0>0\\ \\forall\\delta>0\\ \\exists x_0,t:\\|x_0-x^\\ast\\|<\\delta\\land\\|x(t;x_0)-x^\\ast\\|\\geq\\varepsilon_0', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(695, '3.2.470', 48, 'Attraktivität', 'Ein Gleichgewicht heißt attraktiv, wenn Trajektorien aus einer Umgebung asymptotisch gegen dieses Gleichgewicht konvergieren.', '\\lim_{t\\rightarrow\\infty}x(t;x_0)=x^\\ast', '\\lim_{t\\rightarrow\\infty}x(t;x_0)=x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(696, '3.2.471', 48, 'Asymptotische Stabilität', 'Ein Gleichgewicht heißt asymptotisch stabil, wenn es Lyapunov-stabil und attraktiv ist.', '\\text{stabil}\\land\\lim_{t\\rightarrow\\infty}x(t;x_0)=x^\\ast', '\\text{stabil}\\land\\lim_{t\\rightarrow\\infty}x(t;x_0)=x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(697, '3.2.472', 48, 'Globale asymptotische Stabilität', 'Ein Gleichgewicht heißt global asymptotisch stabil, wenn alle Zustände des betrachteten Zustandsraums gegen dieses Gleichgewicht konvergieren.', '\\forall x_0\\in X:\\lim_{t\\rightarrow\\infty}x(t;x_0)=x^\\ast', '\\forall x_0\\in X:\\lim_{t\\rightarrow\\infty}x(t;x_0)=x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(698, '3.2.473', 48, 'Exponentielle Stabilität', 'Ein Gleichgewicht heißt exponentiell stabil, wenn Zustandsabweichungen mindestens exponentiell abklingen.', '\\|x(t;x_0)-x^\\ast\\|\\leq c e^{-\\lambda t}\\|x_0-x^\\ast\\|', '\\|x(t;x_0)-x^\\ast\\|\\leq c e^{-\\lambda t}\\|x_0-x^\\ast\\|', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(699, '3.2.474', 48, 'Lyapunov-Stabilität eines diskreten Fixpunktes', 'Ein diskreter Fixpunkt heißt stabil, wenn kleine Anfangsstörungen für alle diskreten Zeitpunkte klein bleiben.', '\\forall\\varepsilon>0\\ \\exists\\delta>0:\\|x_0-x^\\ast\\|<\\delta\\Rightarrow\\|x_k-x^\\ast\\|<\\varepsilon', '\\forall\\varepsilon>0\\ \\exists\\delta>0:\\|x_0-x^\\ast\\|<\\delta\\Rightarrow\\|x_k-x^\\ast\\|<\\varepsilon', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(700, '3.2.475', 48, 'Asymptotische Stabilität eines diskreten Fixpunktes', 'Ein diskreter Fixpunkt heißt asymptotisch stabil, wenn er stabil ist und x_k gegen x* konvergiert.', '\\lim_{k\\rightarrow\\infty}x_k=x^\\ast', '\\lim_{k\\rightarrow\\infty}x_k=x^\\ast', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(701, '3.2.476', 48, 'Exponentielle Stabilität eines diskreten Fixpunktes', 'Ein diskreter Fixpunkt heißt exponentiell stabil, wenn seine Abweichung geometrisch abnimmt.', '\\|x_k-x^\\ast\\|\\leq c q^k\\|x_0-x^\\ast\\|', '\\|x_k-x^\\ast\\|\\leq c q^k\\|x_0-x^\\ast\\|', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(702, '3.2.477', 48, 'Jacobi-Matrix des Vektorfeldes', 'Die Jacobi-Matrix enthält die partiellen Ableitungen der Komponenten eines Vektorfeldes.', 'J_f(x)=\\left(\\frac{\\partial f_i}{\\partial x_j}(x)\\right)_{i,j=1}^{n}', 'J_f(x)=\\left(\\frac{\\partial f_i}{\\partial x_j}(x)\\right)_{i,j=1}^{n}', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(703, '3.2.478', 48, 'Linearisierung am Gleichgewicht', 'Die Linearisierung zerlegt die Dynamik in einen linearen Hauptteil und einen höherwertigen Restterm.', '\\dot{\\xi}=A\\xi+r(\\xi),\\quad A=J_f(x^\\ast)', '\\dot{\\xi}=A\\xi+r(\\xi),\\quad A=J_f(x^\\ast)', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(704, '3.2.479', 48, 'Hyperbolisches Gleichgewicht', 'Ein Gleichgewicht heißt hyperbolisch, wenn kein Eigenwert der Jacobi-Matrix einen verschwindenden Realteil besitzt.', '\\operatorname{Re}(\\lambda_i)\\neq0\\quad\\forall i', '\\operatorname{Re}(\\lambda_i)\\neq0\\quad\\forall i', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(705, '3.2.480', 48, 'Stabiles Eigenwertteilgebiet', 'Der stabile Spektralbereich umfasst alle Eigenwerte mit negativem Realteil.', '\\sigma_s(A)=\\{\\lambda\\in\\sigma(A)\\mid\\operatorname{Re}(\\lambda)<0\\}', '\\sigma_s(A)=\\{\\lambda\\in\\sigma(A)\\mid\\operatorname{Re}(\\lambda)<0\\}', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(706, '3.2.481', 48, 'Instabiles Eigenwertteilgebiet', 'Der instabile Spektralbereich umfasst alle Eigenwerte mit positivem Realteil.', '\\sigma_u(A)=\\{\\lambda\\in\\sigma(A)\\mid\\operatorname{Re}(\\lambda)>0\\}', '\\sigma_u(A)=\\{\\lambda\\in\\sigma(A)\\mid\\operatorname{Re}(\\lambda)>0\\}', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(707, '3.2.482', 48, 'Zentrales Eigenwertteilgebiet', 'Der zentrale Spektralbereich umfasst alle Eigenwerte mit verschwindendem Realteil.', '\\sigma_c(A)=\\{\\lambda\\in\\sigma(A)\\mid\\operatorname{Re}(\\lambda)=0\\}', '\\sigma_c(A)=\\{\\lambda\\in\\sigma(A)\\mid\\operatorname{Re}(\\lambda)=0\\}', 'literature', 93, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(708, '3.2.483', 48, 'Attraktor', 'Eine kompakte invariante Menge heißt Attraktor, wenn Zustände aus einer Umgebung asymptotisch zu ihr gelangen.', '\\operatorname{dist}(\\Phi_t(x_0),A)\\rightarrow0', '\\operatorname{dist}(\\Phi_t(x_0),A)\\rightarrow0', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(709, '3.2.484', 48, 'Einzugsgebiet eines Attraktors', 'Das Einzugsgebiet umfasst alle Anfangszustände, deren Trajektorien sich dem Attraktor annähern.', '\\mathcal{B}(A)=\\{x_0\\in X\\mid\\operatorname{dist}(\\Phi_t(x_0),A)\\rightarrow0\\}', '\\mathcal{B}(A)=\\{x_0\\in X\\mid\\operatorname{dist}(\\Phi_t(x_0),A)\\rightarrow0\\}', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(710, '3.2.485', 48, 'Punktattraktor', 'Ein Punktattraktor besteht aus einem einzelnen asymptotisch stabilen Gleichgewicht.', 'A=\\{x^\\ast\\}', 'A=\\{x^\\ast\\}', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(711, '3.2.486', 48, 'Periodischer Attraktor', 'Eine stabile periodische Trajektorie heißt periodischer Attraktor.', 'x(t+T)=x(t)', 'x(t+T)=x(t)', 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(712, '3.2.487', 48, 'Grenzzyklus', 'Ein Grenzzyklus ist eine isolierte geschlossene Trajektorie eines kontinuierlichen dynamischen Systems.', NULL, NULL, 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(713, '3.2.488', 48, 'Seltsamer Attraktor', 'Ein seltsamer Attraktor ist eine anziehende invariante Menge mit komplexer, häufig fraktaler Struktur und empfindlicher Abhängigkeit von Anfangsbedingungen.', NULL, NULL, 'literature', 94, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'Etablierte Definition aus der Theorie dynamischer Systeme.', 'verified', 51),
(714, '3.2.489', 48, 'Funktionaler Gleichgewichtszustand des FRZK', 'Ein Zustand u* heißt funktionaler Gleichgewichtszustand, wenn der FRZK-Entwicklungsoperator keine Zustandsänderung erzeugt.', 'F_{\\mathrm{FRZK}}(u^\\ast)=0', 'F_{\\mathrm{FRZK}}(u^\\ast)=0', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(715, '3.2.490', 48, 'Funktionale Stabilität des FRZK', 'Ein funktionaler Gleichgewichtszustand heißt stabil, wenn kleine Anfangsabweichungen innerhalb eines vorgegebenen Toleranzbereichs verbleiben.', '\\|u_0-u^\\ast\\|<\\delta\\Rightarrow\\|u(t)-u^\\ast\\|<\\varepsilon', '\\|u_0-u^\\ast\\|<\\delta\\Rightarrow\\|u(t)-u^\\ast\\|<\\varepsilon', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(716, '3.2.491', 48, 'Funktionale Attraktivität', 'Ein funktionaler Gleichgewichtszustand heißt attraktiv, wenn die Zustandsabweichung asymptotisch verschwindet.', '\\lim_{t\\rightarrow\\infty}\\|u(t)-u^\\ast\\|=0', '\\lim_{t\\rightarrow\\infty}\\|u(t)-u^\\ast\\|=0', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(717, '3.2.492', 48, 'Funktionaler Attraktor', 'Eine invariante Menge im FRZK-Zustandsraum heißt funktionaler Attraktor, wenn sich Trajektorien aus ihrem Einzugsgebiet asymptotisch annähern.', '\\operatorname{dist}(u(t),A_{\\mathrm{F}})\\rightarrow0', '\\operatorname{dist}(u(t),A_{\\mathrm{F}})\\rightarrow0', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(718, '3.2.493', 48, 'Funktionales Einzugsgebiet', 'Das funktionale Einzugsgebiet enthält alle Anfangszustände, deren Trajektorien gegen einen funktionalen Attraktor konvergieren.', '\\mathcal{B}_{\\mathrm{F}}(A_{\\mathrm{F}})=\\{u_0\\in S\\mid\\operatorname{dist}(u(t;u_0),A_{\\mathrm{F}})\\rightarrow0\\}', '\\mathcal{B}_{\\mathrm{F}}(A_{\\mathrm{F}})=\\{u_0\\in S\\mid\\operatorname{dist}(u(t;u_0),A_{\\mathrm{F}})\\rightarrow0\\}', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(719, '3.2.494', 48, 'Funktionale Drift', 'Die funktionale Drift ist der Normabstand eines Zustands zu einem Referenzzustand.', 'D_{\\mathrm{F}}(t)=\\|u(t)-u_{\\mathrm{ref}}\\|', 'D_{\\mathrm{F}}(t)=\\|u(t)-u_{\\mathrm{ref}}\\|', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(720, '3.2.495', 48, 'Relative funktionale Drift', 'Die relative funktionale Drift normiert den Zustandsabstand auf die Norm des Referenzzustands.', 'D_{\\mathrm{F,rel}}(t)=\\frac{\\|u(t)-u_{\\mathrm{ref}}\\|}{\\|u_{\\mathrm{ref}}\\|}', 'D_{\\mathrm{F,rel}}(t)=\\frac{\\|u(t)-u_{\\mathrm{ref}}\\|}{\\|u_{\\mathrm{ref}}\\|}', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(721, '3.2.496', 48, 'Funktionale Rückkehrrate', 'Die funktionale Rückkehrrate beschreibt die lokale logarithmische Abnahme des Abstands zu einem Referenzzustand.', 'r_{\\mathrm{F}}(t)=-\\frac{\\mathrm{d}}{\\mathrm{d}t}\\ln\\|u(t)-u^\\ast\\|', 'r_{\\mathrm{F}}(t)=-\\frac{\\mathrm{d}}{\\mathrm{d}t}\\ln\\|u(t)-u^\\ast\\|', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(722, '3.2.497', 48, 'Funktionale Störung', 'Eine funktionale Störung ist eine Zustandsabweichung oder externe Einwirkung auf das FRZK-Entwicklungsgesetz.', '\\dot{u}=F_{\\mathrm{FRZK}}(u)+\\eta(t)', '\\dot{u}=F_{\\mathrm{FRZK}}(u)+\\eta(t)', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(723, '3.2.498', 48, 'Funktionale Robustheit', 'Ein funktionaler Zustand heißt robust, wenn zulässige Störungen nur begrenzte Zustandsabweichungen hervorrufen.', '\\sup_{t\\geq0}\\|u_\\eta(t)-u_0(t)\\|\\leq C\\|\\eta\\|_{\\mathcal{H}}', '\\sup_{t\\geq0}\\|u_\\eta(t)-u_0(t)\\|\\leq C\\|\\eta\\|_{\\mathcal{H}}', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(724, '3.2.499', 48, 'Funktionale Resilienz', 'Funktionale Resilienz bezeichnet die Rückkehr in das Einzugsgebiet eines funktionalen Attraktors nach einer zeitlich begrenzten Störung.', '\\operatorname{dist}(u(t),A_{\\mathrm{F}})\\rightarrow0', '\\operatorname{dist}(u(t),A_{\\mathrm{F}})\\rightarrow0', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
(725, '3.2.500', 48, 'Funktionaler Stabilitätsbereich', 'Der funktionale Stabilitätsbereich enthält alle Anfangszustände, für die die gewählte Stabilitätsbedingung erfüllt ist.', '\\mathcal{S}_{\\mathrm{stab}}(u^\\ast)=\\{u_0\\in S\\mid u(t;u_0)\\text{ erfüllt die Stabilitätsbedingung}\\}', '\\mathcal{S}_{\\mathrm{stab}}(u^\\ast)=\\{u_0\\in S\\mid u(t;u_0)\\text{ erfüllt die Stabilitätsbedingung}\\}', 'original', NULL, 'Voraussetzungen gemäß Abschnitt 3.2.31.', 'FRZK-spezifische Eigenkonstruktion; empirische Operationalisierung gesondert erforderlich.', 'verified', 51),
